    codeExample: "<section class=\"teabowl\">\n  <h1>Nothing here<br/>is <em>finished.</em></h1>\n  <p>Objects and software, mended with gold.</p>\n  <a class=\"seam-link\" href=\"#\">See the collection</a>\n</section>",
