    spacing: {"baseUnit":"8px","marginScale":"24 / 64 / 120","paddingScale":"20 / 32 / 48","grid":"Art 320px + copy fluid; 3-up episode grid under the fold"},
    motion: {"pageLoad":"Waveform bars rise in sequence, 500ms, once","hoverStates":"Wash + underline draw, 220ms","transitions":"Smooth, 200–260ms","scroll":"Playing episode card stays docked as a mini-player"},
