    responsive: "Portrait cards stack; arches keep safe area. Folder tabs become pill headers under 720px. Display clamps 2.5rem→3.6rem.",
    spacing: {"baseUnit":"8px","marginScale":"20 / 48 / 88 / 144","paddingScale":"22 / 40 / 60","grid":"Kennel 1100px; portrait cards 3-col"},
    motion: {"pageLoad":"Cards unzip from tab edge, 300ms staggered","hoverStates":"Tab lift + arch tilt 220ms","transitions":"Soft, warm, eager","scroll":"Dashed rules scroll with content; arches static"},
